arguments.http_method:
{%- set vin = vars.input.params['http_method'] -%}
{%- if vin not in vars.empty -%}
{{vin|upper}}
{%- else -%}
GET
{%- endif -%}

arguments.input_payload:
{%- set vin = vars.input.params['data_payload'] -%}
{%- if vin not in vars.empty -%}
{{vin}}
{%- else -%}
{}
{%- endif -%}

arguments.legacy_version:
{%- set v = vars.version -%}
{%- if v[0] == 7 and v[1] == 2 and v[2] < 8 -%}
true
{%- elif v[0] == 7 and v[1] == 4 and v[2] < 4 -%}
true
{%- else -%}
false
{%- endif -%}

arguments.revision_search:
{%- set ret = {} -%}
{%- set search = vars.comment_search -%}
{%- set results = vars.revisions 
| json_query( "[?contains(comment,'{}')]".format(search) ) -%}
{%- if results and results|length > 0 -%}
  {%- set do = ret.update(results[0]) -%}
  {%- set do = ret.update({"version":vars.categories[results[0].version_id] }) -%}
{%- else -%}
{%- set do = ret.update([]) -%}
{%- endif -%}
{{ret}}

schema.description:
{%- for r in vars.revision_data %}

----------------------------------------------------------

|  {{r.params.fos_ip}} | {{r.output.serial}} | {{r.output.version}} |
|  ------------------------  | ----------------------  | ------------------------ |

| Revision ID | Firmware | Comment | 
| ------------- | ----------- | ----------- |
{%- set catg = r.output.results.categories %}
{%- for rev in r.output.results.revisions %}
{%- set ver = [ 
  catg[rev.version_id].major_version,
  catg[rev.version_id].minor_version,
  catg[rev.version_id].patch_number,
  catg[rev.version_id].build_number
] %}
| {{rev.id}} | v{{ver[0]}}.{{ver[1]}}.{{ver[2]}} (Build {{ver[3]}}) | {{rev.comment}} |
{%- endfor %}

{% endfor %}

| FG | Revision ID | Timestamp |  Comment |
| --- | ------------- | ------------- | ------------ |
{%- for r in vars.revision_data %}
{%- set o = r.output %}
|  {{r.params.fos_ip}} | {{o.id}} | {{arrow.get(o.time).to("UTC").format("YYYY-MM-DD HH:mm:ss ZZ")}} | {{o.comment}} |
{%- endfor %}

arguments.revert_list:
{%- set table = [] -%}
{%- for r in vars.revision_data %}
{%- set idx = {} -%}
{%- set o = r.output -%}
{%- set _do = idx.update({"ip":r.params.fos_ip}) -%}
{%- set _do = idx.update({"id":o.id}) -%}
{%- set _do = table.append(idx) -%}
{%- endfor -%}
{{table}}

arguments.payload:
{%- set payload = {} -%}
{%- set params = [] -%}
{%- set _do = payload.update({"id":1,"method":vars.method,"session":vars.session}) -%}
{%- set _do = params.append({"url":vars.url_api}) -%}
{%- set _do = payload.update({"params":params}) -%}
{{payload}}

arguments.payload_updatetemplate:
{%- set data = vars.steps.fmgapi_gettemplate.data.result[0].data -%}
{%- set _do = data["fwmprof setting"].update({ "description" : "Updated " + arrow.utcnow().int_timestamp|string }) -%}
{
  "id": 1,
  "method": "update",
  "params": [
    {
      "data": {{data}},
      "url": "{{vars.firmware_url}}"
    }
  ],
  "session": "{{vars.session}}"
}
